// Declaration Precedence & Parsing Rules (C/C++)

// 1. Array of 10 pointers to int ([] binds first)
int* ptr_arr[10];

// 2. Pointer to an array of 10 ints
int (*arr_ptr)[10];

// 3. Pointer to a const int (data is const)
const int *pci;

// 4. Const pointer to an int (pointer itself is const)
int * const cip;

// 5. Function Pointer: ptr to func taking float, returning char*
char* (*func_ptr)(float);

// 6. Pointer to an array of 5 function pointers
// (Functions take double, return int)
int (*(*complex_arr_ptr)[5])(double);

// 7. Type aliasing for readability
typedef char* (*LoggerFunc)(const char*);
LoggerFunc global_log_fnc;
